<?php
require __DIR__ . '/includes/bootstrap.php';
require __DIR__ . '/includes/ai.php';
$user=require_role('admin'); $id=(int)($_GET['id'] ?? $_POST['id'] ?? 0); $pdo=db();
$q=$pdo->prepare('SELECT r.*,u.name worker,p.name project_name FROM reports r JOIN users u ON u.id=r.user_id LEFT JOIN projects p ON p.id=r.project_id WHERE r.id=?'); $q->execute([$id]); $report=$q->fetch(); if (!$report) { http_response_code(404); exit('Report not found.'); }
if ($_SERVER['REQUEST_METHOD']==='POST') {
    check_csrf();
    if (($_POST['action'] ?? '') === 'retry_ai') {
        $q=$pdo->prepare('SELECT filename,mime FROM report_photos WHERE report_id=? ORDER BY id'); $q->execute([$id]); $images=[];
        foreach ($q->fetchAll() as $photo) { $path=__DIR__.'/storage/uploads/'.basename($photo['filename']); if (is_file($path)) $images[]=['path'=>$path,'mime'=>$photo['mime']]; }
        if (!$images) { flash('No original photos available for analysis.','error'); redirect('report.php?id='.$id); }
        if (function_exists('set_time_limit')) @set_time_limit(120);
        try { [$aiStatus,$aiData,$aiError]=analyze_report($report['type'],$images); $q=$pdo->prepare('UPDATE reports SET ai_status=?,ai_data=?,ai_error=? WHERE id=?'); $q->execute([$aiStatus,$aiData,$aiError,$id]); audit((int)$user['id'],$id,'AI analysis retried',$aiStatus); flash($aiStatus==='completed'?'AI analysis updated. Review all suggestions.':'AI analysis unavailable. Check the status below.', $aiStatus==='completed'?'success':'error'); } catch (Throwable $e) { flash('AI analysis failed.','error'); }
        redirect('report.php?id='.$id);
    }
    $status=(string)($_POST['status'] ?? ''); $project=(int)($_POST['project_id'] ?? 0); $amount=trim((string)($_POST['amount'] ?? '')); $category=trim((string)($_POST['category'] ?? '')); $notes=trim((string)($_POST['notes'] ?? ''));
    if (!in_array($status,['pending','approved','rejected'],true) || ($amount!=='' && (!is_numeric($amount) || (float)$amount<0 || (float)$amount>9999999999 || !preg_match('/^\d+(?:\.\d{1,2})?$/',$amount))) || strlen($category)>100 || strlen($notes)>5000) { flash('Please check the review fields. Amount must have up to two decimal places.', 'error'); redirect('report.php?id='.$id); }
    if ($report['type'] === 'expense' && $status === 'approved' && $amount === '') { flash('Enter an amount before approving an expense.', 'error'); redirect('report.php?id='.$id); }
    if ($report['type'] !== 'expense' && $amount !== '') { flash('Amounts are only available for expense reports.', 'error'); redirect('report.php?id='.$id); }
    if ($project) { $q=$pdo->prepare('SELECT id FROM projects WHERE id=?'); $q->execute([$project]); if (!$q->fetchColumn()) { flash('Project not found.', 'error'); redirect('report.php?id='.$id); } }
    try {
        $pdo->beginTransaction(); $q=$pdo->prepare('UPDATE reports SET status=?,project_id=?,amount=?,category=?,notes=? WHERE id=?'); $q->execute([$status,$project ?: null,$amount!==''?$amount:null,$category,$notes,$id]);
        $changes=json_encode(['before'=>['status'=>$report['status'],'project_id'=>$report['project_id'],'amount'=>$report['amount'],'category'=>$report['category'],'notes'=>$report['notes']], 'after'=>['status'=>$status,'project_id'=>$project ?: null,'amount'=>$amount!==''?$amount:null,'category'=>$category,'notes'=>$notes]],JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);
        audit((int)$user['id'],$id,'review updated',$changes ?: 'Review updated'); $pdo->commit(); flash('Review saved.');
    } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); flash('Could not save the review.', 'error'); }
    redirect('report.php?id='.$id);
}
$q=$pdo->prepare('SELECT * FROM report_photos WHERE report_id=? ORDER BY id'); $q->execute([$id]); $photos=$q->fetchAll(); $projects=$pdo->query('SELECT id,name FROM projects ORDER BY name')->fetchAll();
$q=$pdo->prepare('SELECT a.*,u.name FROM audit_log a JOIN users u ON u.id=a.actor_id WHERE a.report_id=? ORDER BY a.created_at DESC,a.id DESC'); $q->execute([$id]); $history=$q->fetchAll();
$ai=$report['ai_data'] ? json_decode($report['ai_data'],true) : null;
if (is_array($ai)) foreach (['summary','merchant','receipt_date','currency','category','image_quality','uncertainty'] as $field) if (is_string($ai[$field] ?? null)) $ai[$field]=clean_ai_text($ai[$field]);
page_start('Report review',$user,'dashboard');
?>
<a class="back-link" href="admin.php#reports">← Back to reports</a><div class="heading-row"><div><div class="eyebrow">FIELD REPORT / #<?=e((string)$id)?></div><h1><?=e(ucfirst($report['type']))?> report</h1><p>Submitted by <?=e($report['worker'])?> · <?=e(date('d M Y, H:i',strtotime($report['created_at'])))?></p></div><span class="status <?=e($report['status'])?>"><?=e($report['status'])?></span></div>
<div class="detail-layout"><div><section class="panel"><div class="section-heading"><div><span class="step-label">ORIGINAL EVIDENCE</span><h2>Submitted photos</h2><p>Open an image to view it at full size.</p></div></div><div class="photo-grid"><?php foreach($photos as $photo): ?><a href="photo.php?id=<?=$photo['id']?>" target="_blank" rel="noopener"><img src="photo.php?id=<?=$photo['id']?>" alt="Report photo"></a><?php endforeach; ?></div></section>
<section class="panel ai-panel"><div class="section-heading"><div><span class="step-label">✦ GEMINI ASSIST</span><h2>AI insights</h2><p>Suggestions only. Always verify against the original photos.</p></div><span class="pill light"><?=e(str_replace('_',' ',$report['ai_status']))?></span></div>
<?php if(is_array($ai)): ?><div class="ai-summary"><?=e($ai['summary'] ?? 'No summary available.')?></div><div class="insight-grid"><div><small>MERCHANT</small><strong><?=e($ai['merchant'] ?? 'Not identified')?></strong></div><div><small>SUGGESTED AMOUNT</small><strong><?=isset($ai['amount']) ? e((string)$ai['amount']).' '.e($ai['currency'] ?? '') : 'Not identified'?></strong></div><div><small>RECEIPT DATE</small><strong><?=e($ai['receipt_date'] ?? 'Not identified')?></strong></div><div><small>CATEGORY</small><strong><?=e($ai['category'] ?? 'Not identified')?></strong></div></div><div class="ai-warning">⚠ Image quality: <?=e($ai['image_quality'] ?? 'unknown')?>. <?=e($ai['uncertainty'] ?? 'Review all extracted information carefully.')?></div><?php else: ?><div class="ai-warning">Analysis unavailable. <?=e($report['ai_error'] ?? 'Configure Gemini in .env and review this report manually.')?></div><?php endif; ?><form method="post" class="retry-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="retry_ai"><button class="button secondary compact">↻ Retry analysis</button></form><div class="small-muted">Email notification: <?=e(str_replace('_',' ',$report['email_status']))?> · “Sent” means accepted by the server, not confirmed delivered.</div></section>
<section class="panel"><div class="section-heading"><div><span class="step-label">ACCOUNTABILITY</span><h2>Activity log</h2></div></div><?php foreach($history as $h): ?><div class="log-item"><span class="log-dot"></span><div><strong><?=e(ucfirst($h['action']))?></strong><small><?=e($h['name'])?> · <?=e($h['created_at'])?></small><?php if($h['details']): ?><details><summary>View details</summary><pre><?=e($h['details'])?></pre></details><?php endif; ?></div></div><?php endforeach; ?></section></div>
<aside class="panel review-panel"><span class="step-label">MANAGEMENT REVIEW</span><h2>Review &amp; decide</h2><p>Confirm the details before approving.</p><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Project<select name="project_id"><option value="">Unassigned</option><?php foreach($projects as $p): ?><option value="<?=$p['id']?>" <?=$report['project_id']==$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach; ?></select></label><?php if($report['type']==='expense'): ?><label>Amount (AED)<input type="number" name="amount" min="0" max="9999999999" step="0.01" value="<?=e($report['amount'])?>" placeholder="0.00"></label><label>Expense category<input name="category" maxlength="100" list="categories" value="<?=e($report['category'])?>" placeholder="Choose or type a category"><datalist id="categories"><option value="Fuel"><option value="Vehicle service"><option value="Washing"><option value="Labor"><option value="Materials"><option value="Transportation"><option value="Other"></datalist></label><?php else: ?><input type="hidden" name="category" value="<?=e($report['category'])?>"><?php endif; ?><label>Notes<textarea name="notes" maxlength="5000" rows="5" placeholder="Add a note for your team..."><?=e($report['notes'])?></textarea></label><label>Review status<select name="status"><option value="pending" <?=$report['status']==='pending'?'selected':''?>>Pending</option><option value="approved" <?=$report['status']==='approved'?'selected':''?>>Approved</option><option value="rejected" <?=$report['status']==='rejected'?'selected':''?>>Rejected</option></select></label><button class="button primary wide">Save review <span>→</span></button></form></aside></div>
<?php page_end(); ?>
